function assertNonNegativeFinite(value, name) {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError(`${name} must be a finite nonnegative number`);
  }
}

export function retryDelay(attempt, { baseDelay = 10, maxDelay = 1000, maxAttempts } = {}) {
  assertPositiveInteger(attempt, 'attempt');
  if (maxAttempts !== undefined) {
    assertPositiveInteger(maxAttempts, 'maxAttempts');
  }
  assertNonNegativeFinite(baseDelay, 'baseDelay');
  assertNonNegativeFinite(maxDelay, 'maxDelay');
  if (baseDelay === 0) {
    return 0;
  }
  const scaled = baseDelay * 2 ** (attempt - 1);
  if (!Number.isFinite(scaled)) {
    return maxDelay;
  }
  return Math.min(maxDelay, scaled);
}

