import { retryDelay } from './retry-delay.mjs';

function assertPositiveInteger(value, name) {
  if (!Number.isInteger(value) || value < 1) {
    throw new RangeError(`${name} must be a positive integer`);
  }
}

function assertNonNegativeFinite(value, name) {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError(`${name} must be a finite nonnegative number`);
  }
}

function assertFunction(value, name) {
  if (typeof value !== 'function') {
    throw new TypeError(`${name} must be a function`);
  }
}

export async function runWithRetry(operation, options = {}) {
  const {
    maxAttempts = 3,
    baseDelay = 10,
    maxDelay = 1000,
    shouldRetry = () => true,
    sleep = async () => {},
  } = options;

  assertFunction(operation, 'operation');
  assertPositiveInteger(maxAttempts, 'maxAttempts');
  assertNonNegativeFinite(baseDelay, 'baseDelay');
  assertNonNegativeFinite(maxDelay, 'maxDelay');
  assertFunction(shouldRetry, 'shouldRetry');
  assertFunction(sleep, 'sleep');

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await operation(attempt);
    } catch (reason) {
      if (attempt === maxAttempts) {
        throw reason;
      }
      const permit = await shouldRetry(reason, attempt);
      if (!permit) {
        throw reason;
      }
      await sleep(retryDelay(attempt, { baseDelay, maxDelay }), attempt + 1);
    }
  }
}

